        (*Out_Arccos) = ((LQ_I_8BIT)64 - LQ_INT8_Q1_ARCSIN_ARCCOS_PU_512_SUBDIVIDE_TABLE[(uhindex & 0x00FFu)]);
        break;
    case 0x0000u:
        (*Out_Arcsin) = (-LQ_INT8_Q1_ARCSIN_ARCCOS_PU_512_SUBDIVIDE_TABLE[0x00FFu - (uhindex & 0x00FFu)]);
        (*Out_Arccos) = ((LQ_I_8BIT)64 + LQ_INT8_Q1_ARCSIN_ARCCOS_PU_512_SUBDIVIDE_TABLE[0x00FFu - (uhindex & 0x00FFu)]);
        break;
